        app.MapGet("/api/v1/fleet/endpoints/{id:guid}/health", EndpointHealth).RequirePermission("response:read");
        app.MapPost("/api/v1/fleet/tags:apply", ApplyTags).RequirePermission("platform:admin");
        app.MapGet("/api/v1/fleet/groups", Groups).RequirePermission("response:read");
        app.MapPost("/api/v1/fleet/groups", CreateGroup).RequirePermission("platform:admin");
        app.MapPut("/api/v1/fleet/groups/{id:guid}", UpdateGroup).RequirePermission("platform:admin");
        app.MapGet("/api/v1/fleet/ring-policies/{id:guid}", Rings).RequirePermission("response:read");
        app.MapPut("/api/v1/fleet/ring-policies/{id:guid}", PutRings).RequirePermission("platform:admin");
        app.MapGet("/api/v1/agent-update/packages", Packages).RequirePermission("response:read");
        app.MapGet("/api/v1/agent-update/packages/{id:guid}", Package).RequirePermission("response:read");
        app.MapPost("/api/v1/agent-update/packages", RegisterPackage).RequirePermission("platform:admin");
        app.MapPost("/api/v1/agent-update/packages/{id:guid}:revoke", RevokePackage).RequirePermission("platform:admin");
        app.MapPut("/api/v1/agent-update/policies/{id:guid}", PutPolicy).RequirePermission("platform:admin");
        app.MapGet("/api/v1/agent-update/policies/{id:guid}", Policy).RequirePermission("response:read");
        app.MapPost("/api/v1/agent-update/rollouts:preview", Preview).RequirePermission("platform:admin");
        app.MapPost("/api/v1/agent-update/rollouts", CreateRollout).RequirePermission("platform:admin");
        app.MapGet("/api/v1/agent-update/rollouts", Rollouts).RequirePermission("response:read");
        app.MapGet("/api/v1/agent-update/rollouts/{id:guid}", Rollout).RequirePermission("response:read");
        foreach (var transition in new[] { "start", "pause", "resume", "cancel", "advance" }) { var t = transition; app.MapPost($"/api/v1/agent-update/rollouts/{{id:guid}}:{t}", (Guid id, TransitionRequest input, HttpContext c, IFleetUpdateRepository r, CancellationToken ct) => Transition(id, t, input, c, r, ct)).RequirePermission("platform:admin"); }
        app.MapGet("/api/v1/agent-update/health", Health).RequirePermission("response:read");
        app.MapGet("/api/v1/agent-update/audit", Audit).RequirePermission("response:read");
        app.MapGet("/agent/v1/updates/assignment", AgentAssignment).RequirePermission("agent:heartbeat");
        app.MapGet("/agent/v1/updates/packages/{assignment:guid}/manifest", AgentPackage).RequirePermission("agent:heartbeat");
        app.MapGet("/agent/v1/updates/packages/{assignment:guid}/content", AgentPackageContent).RequirePermission("agent:heartbeat");
        app.MapPost("/agent/v1/updates/status", AgentStatus).RequirePermission("agent:heartbeat");
        app.MapPost("/internal/v1/agent-update/self-test", SelfTest).RequirePermission("platform:admin");
    }
