    static async Task<IResult> Endpoints(HttpContext c, IFleetUpdateRepository f, IEndpointRepository e, IResponseActionRepository t, IAgentProtectionRepository p, CancellationToken ct) { var v = await Views(c, f, e, t, p, ct); var search = c.Request.Query["search"].FirstOrDefault(); if (!string.IsNullOrWhiteSpace(search)) v = v.Where(x => x.Hostname.Contains(search, StringComparison.OrdinalIgnoreCase) || x.AgentVersion.Contains(search, StringComparison.OrdinalIgnoreCase) || x.Tags.Any(y => y.Contains(search, StringComparison.OrdinalIgnoreCase))).ToArray(); return Ok(c, new { items = v, count = v.Count }); }
    static async Task<IResult> Endpoint(Guid id, HttpContext c, IFleetUpdateRepository f, IEndpointRepository e, IResponseActionRepository t, IAgentProtectionRepository p, CancellationToken ct) => (await Views(c, f, e, t, p, ct)).SingleOrDefault(x => x.EndpointId == id) is { } x ? Ok(c, x) : Results.NotFound();
    static async Task<IResult> EndpointVersions(Guid id, HttpContext c, IFleetUpdateRepository f, CancellationToken ct) { var a = (await f.RolloutsAsync(Tenant(c), ct)); var history = new List<EndpointUpdateAssignment>(); foreach (var r in a) history.AddRange((await f.AssignmentsAsync(Tenant(c), r.RolloutId, ct)).Where(x => x.EndpointId == id)); return Ok(c, history.OrderByDescending(x => x.UpdatedAt).ToArray()); }
